toad_implementation.code_blueprint:
canvas {
  size: 800px 900px;
  fill: #FAFAFA;
  font-family: "Outfit, sans-serif";
}

>indigo = #4F46E5;
>coral = #F43F5E;
>slate = #334155;
>cardWhite = #FFFFFF;
>border = #E2E8F0;

rect #welcomeCard {
  at: center of canvas;
  size: 680px 780px;
  fill: >cardWhite;
  stroke: >border;
  stroke-width: 1px;
  radius: 20px;
}

text #welcomeGreeting {
  at: top center of #welcomeCard offset 0px 48px;
  content: "WELCOME TO THE TEAM!";
  font-size: 32px;
  font-weight: 700;
  color: >indigo;
}

text #employeeName {
  at: below #welcomeGreeting offset 12px;
  content: "WE ARE THRILLED TO HAVE YOU ON BOARD";
  font-size: 13px;
  font-weight: 600;
  color: >coral;
}

rect #step1Card {
  at: below #employeeName offset 40px;
  size: 580px 72px;
  fill: #F8FAFC;
  stroke: >border;
  stroke-width: 1px;
  radius: 12px;
}

circle #step1Bullet {
  at: left center of #step1Card offset 20px 0px;
  size: 32px;
  fill: >indigo;
}

text #step1Check {
  at: center of #step1Bullet;
  content: "1";
  font-size: 14px;
  font-weight: 700;
  color: #FFFFFF;
}

text #step1Text {
  at: right of #step1Bullet offset 18px;
  content: "Meet your Onboarding Buddy at 10:00 AM";
  font-size: 15px;
  font-weight: 600;
  color: >slate;
}

rect #step2Card {
  at: below #step1Card offset 16px;
  size: 580px 72px;
  fill: #F8FAFC;
  stroke: >border;
  stroke-width: 1px;
  radius: 12px;
}

circle #step2Bullet {
  at: left center of #step2Card offset 20px 0px;
  size: 32px;
  fill: >coral;
}

text #step2Check {
  at: center of #step2Bullet;
  content: "2";
  font-size: 14px;
  font-weight: 700;
  color: #FFFFFF;
}

text #step2Text {
  at: right of #step2Bullet offset 18px;
  content: "Set up your Dev Environment & Security Keys";
  font-size: 15px;
  font-weight: 600;
  color: >slate;
}
